style.css:
/* Roblox Dark Theme */
body {
    background: #0f0f10 !important;
    color: #ffffff !important;
}

/* Main website */
html,
body {
    background:
        radial-gradient(circle at 50% 0%, #252525 0%, #151515 45%, #0b0b0c 100%) !important;
}

/* Navigation / sidebar */
nav,
header,
aside {
    background: #151515 !important;
    border-color: #2b2b2b !important;
}

/* Cards and panels */
div[class*="card"],
div[class*="panel"],
section {
    background-color: #191919 !important;
    border-color: #2d2d2d !important;
}

/* Buttons */
button {
    background: #2b2b2b !important;
    color: white !important;
    border: 1px solid #3a3a3a !important;
    border-radius: 8px !important;
}

button:hover {
    background: #3a3a3a !important;
}

/* Links */
a {
    color: #ffffff !important;
}

a:hover {
    color: #ffb08f !important;
}

/* Roblox-style orange accent */
input:focus,
textarea:focus,
button:focus {
    outline: 2px solid #ff9f7a !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #111111;
}

::-webkit-scrollbar-thumb {
    background: #3a3a3a;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #555555;
}
